/**
 * Metadata tables whose records commonly carry scripts that NowUnit extracts and tests.

 * For every other table `sys_name` is dropped from `data` (it is platform-managed and surfaced
 * only as the generated export/variable name).
 */
export const CommonNowUnitScriptTables = new Set<string>([
    'sys_script_fix', // Fix Script
    'sys_processor', // Processor
    'sys_ux_client_script', // UX (Next Experience) Client Script
    'sys_ux_client_script_include', // UX Client Script Include
    'sys_ux_data_broker_transform', // UX Data Broker Transform
    'sys_ux_data_broker_scriptlet', // UX Data Broker Scriptlet
    'sys_relationship', // Relationship (query/apply scripts)
])

const VIEW_TABLE = 'sys_ui_view'

// Referenced tables for which the platform's generic reference fixup - replacing a minted sys_id
// with the coalesce key value stored in the field's XML attribute - is confirmed to work on both
// create and update. Only add a table here once update-time behavior has actually been verified;
// see TABLES_WITH_CUSTOM_REFERENCE_LOADER for the opt-out that applies regardless of this set.
const VERIFIED_REFERENCE_FIXUP_TABLES = new Set<string>([VIEW_TABLE, 'sys_user_role'])

// Source tables whose own record loader (e.g. the dictionary loader for sys_dictionary) does not
// honor the coalesce key XML attribute during update, even for a referenced table listed in
// VERIFIED_REFERENCE_FIXUP_TABLES. Reference fields on these tables are always passed through
// as-is instead of being reference-fixed up.
const TABLES_WITH_CUSTOM_REFERENCE_LOADER = new Set<string>(['sys_dictionary'])

/**
 * Returns the referenced record's coalesce key/value pairs, or undefined when the column isn't
 * a reference that can be addressed by its coalesce keys.
 *
 * The platform exports reference fields with the target's coalesce keys as XML attributes
 * (`<view name="customview">9b6d...</view>`), which the parser preserves on the field shape.
 * Looking up `referenceTable`'s coalesce strategy tells us which of those attributes to read, so
 * a reference can be rendered in the generated Fluent as e.g. `view: 'customview'` instead of an
 * opaque sys_id.
 *
 * Columns the parser already resolved arrive as a `RecordId` and are left alone, with one
 * exception: the platform's built-in default view is exported as `<view name="NULL">Default
 * view</view>`, which the parser resolves to a `RecordId` whose only coalesce key is `name:
 * 'NULL'`. Left alone, that would generate Fluent code with the literal value `'NULL'` for the
 * view field, which wouldn't build correctly on a subsequent build. That key is extracted here so
 * the caller can detect this case and emit the `default_view` identifier instead.
 */
function extractCoalesceValue(shape: StringShape | undefined, referenceTable: string, plugins: Plugins) {
    if (!shape || shape.isRecordId() || shape.isEmpty()) {
        if (referenceTable === VIEW_TABLE && shape?.ifRecordId()?.hasPrimaryKey()) {
            const recordId = shape.asRecordId()
            return Object.keys(recordId.getKeys()!).map((key): [string, string] => [key, recordId.getPrimaryKey()])
        }
        return undefined
    }

    const coalesceStrategy = plugins.getCoalesceStrategy(referenceTable)
    if (!coalesceStrategy || !Array.isArray(coalesceStrategy)) {
        return undefined
    }

    const coalesceEntries: [key: string, value: string][] = []
    for (const key of coalesceStrategy) {
        const value = shape.getXmlAttributes()[key]
        if (value === undefined) {
            return undefined
        }
        coalesceEntries.push([key, value])
    }
    return coalesceEntries
}

export const RecordPlugin = Plugin.create({
    name: 'RecordPlugin',
    records: {
        '*': {
            getUpdateName(record) {
                return {
                    success: true,
                    value: `${record.getTable()}_${record.getId().getValue()}`,
                }
            },
            async diff(existing, incoming) {
                const changeDatabase = existing.compare(incoming)
                return {
                    success: true,
                    value: changeDatabase.hasChanges() ? new Database(changeDatabase.query()) : new Database(),
                }
            },
            async toShape(record, { compiler, factory, plugins }) {
                const tableName = record.getTable()
                const columnTypes = compiler.getTableColumnTypes(tableName)
                const mandatoryColumns = compiler.getMandatoryColumns(tableName)
                const referenceColumns = compiler.getTableReferenceColumns(tableName)

                // createReference() is async and record.transform()'s callback is not, so resolve these first.
                const references = new Map<string, Shape>()
                for (const [column, referenceTable] of referenceColumns ?? []) {
                    const colValue = record.get(column)?.ifString()
                    const coalesceEntries = extractCoalesceValue(colValue, referenceTable, plugins)
                    const [coalesceEntry, ...extraEntries] = coalesceEntries ?? []
                    if (
                        !colValue ||
                        !coalesceEntry ||
                        extraEntries.length > 0 ||
                        !VERIFIED_REFERENCE_FIXUP_TABLES.has(referenceTable) ||
                        TABLES_WITH_CUSTOM_REFERENCE_LOADER.has(tableName)
                    ) {
                        continue
                    }

                    const [coalesceKey, coalesceKeyValue] = coalesceEntry

                    references.set(
                        column,
                        referenceTable === VIEW_TABLE && colValue.asString().getValue() === DEFAULT_VIEW
                            ? new IdentifierShape({ source: record, name: 'default_view' })
                            : await factory.createReference({
                                  source: colValue,
                                  table: referenceTable,
                                  guid: colValue.getValue(),
                                  keys: { [coalesceKey]: coalesceKeyValue },
                              })
                    )
                }

                // Keep sys_name in `data` for script-bearing metadata so it survives the round trip
                // (NowUnit names extracted scripts by sys_name); drop it for everything else.
                const preserveSysName = CommonNowUnitScriptTables.has(tableName)

                const dataProperties = record.transform(({ $ }) =>
                    Object.fromEntries(
                        record
                            .keys()
                            .filter(
                                (key) =>
                                    (preserveSysName || key !== 'sys_name') &&
                                    key !== 'sys_scope' &&
                                    key !== 'sys_update_name'
                            )
                            .map((key) => {
                                const shape = record.get(key)

                                if (references.has(key)) {
                                    return [key, $.val(references.get(key))]
                                }

                                if (columnTypes?.has(key) && shape?.isString()) {
                                    const expectedType = columnTypes.get(key)
                                    try {
                                        if (expectedType === 'boolean') {
                                            return [key, $.val(shape.toBoolean())]
                                        } else if (expectedType === 'number') {
                                            return [key, $.val(shape.toNumber())]
                                        } else if (expectedType === 'array') {
                                            return [key, $.val(shape.asString().split(',')).def([''])]
                                        } else if (expectedType === 'array-optional') {
                                            const arrayParts = shape.asString().includes(',')
                                            return [key, arrayParts ? $.val(shape.asString().split(',')).def(['']) : $]
                                        }
                                    } catch {
                                        // Keep as string if conversion fails
                                    }
                                }

                                // Mandatory string fields must always be written to avoid build errors
                                // from missing required properties in Data<T>.
                                return [key, shape?.isString() ? (mandatoryColumns?.has(key) ? $ : $.def('')) : $]
                            })
                    )
                )

                const value = new CallExpressionShape({
                    source: record,
                    callee: 'Record',
                    exportName: record.get('sys_name')?.ifDefined()?.asString().getValue(),
                    args: [
                        {
                            $id: NowIdShape.from(record),
                            table: tableName,
                            data: dataProperties,
                        },
                    ],
                })

                return {
                    success: true,
                    value,
                }
            },
            async toFile(record, { database }) {
                const recordBuilder = unloadBuilder(record.getTable())
                const builder = recordBuilder.record(record)

                record
                    .entries()
                    .sort(([a], [b]) => a.localeCompare(b)) // Sort keys to make outputs more deterministic
                    .forEach(([prop, shape]) => builder.field(prop, shape))

                const updateName = record.get('sys_update_name').asString().getValue()
                const claims = database
                    .query('sys_claim')
                    .filter((claim) => claim.get('metadata_update_name').equals(updateName))

                for (const claim of claims) {
                    const claimBuilder = recordBuilder.record(claim)
                    claim
                        .entries()
                        .sort(([a], [b]) => a.localeCompare(b)) // Sort keys to make outputs more deterministic
                        .forEach(([prop, shape]) => claimBuilder.field(prop, shape))
                }

                // sys_es_latest_script can attach to any script-bearing record. It's written into the
                // same file as its parent here, same as sys_claim above
                const esLatestSibling = database
                    .query('sys_es_latest_script')
                    .find((sibling) => sibling.get('id').equals(record.getId().getValue()))

                if (esLatestSibling) {
                    const esLatestBuilder = recordBuilder.record(esLatestSibling)
                    esLatestSibling
                        .entries()
                        .sort(([a], [b]) => a.localeCompare(b))
                        .forEach(([prop, shape]) => esLatestBuilder.field(prop, shape))
                }

                return {
                    success: true,
                    value: {
                        source: record,
                        name: `${updateName}.xml`,
                        category: record.getInstallCategory(),
                        content: recordBuilder.end(),
                    },
                }
            },
        },
    },
    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            async toRecord(callExpression, { factory, diagnostics, plugins, compiler }) {
                if (callExpression.getCallee() !== 'Record') {
                    return { success: false }
                }

                const record = callExpression.getArgument(0).asObject()
                const table = record.get('table').asString().getValue()
                const refColumns = plugins.getReferenceColumns(table)
                const schemaRefColumns = compiler.getTableReferenceColumns(table)
                const tableOwningPlugin = TableOwnership[table as keyof typeof TableOwnership]
                if (tableOwningPlugin) {
                    diagnostics.hint(
                        callExpression,
                        `For a better experience, consider using the ${tableOwningPlugin} API`
                    )
                }

                const dataObj = record.get('data').asObject()

                const properties: { [key: string]: unknown } = {}
                for (const k of dataObj.keys()) {
                    const value = dataObj.get(k)
                    // Prefer the plugin's declaration; fall back to what the table's schema reveals.
                    const refTable = refColumns[k] ?? schemaRefColumns?.get(k)
                    const refValue = refTable ? value?.ifStringLiteral()?.getValue() : undefined

                    if (
                        refValue !== undefined &&
                        refTable &&
                        VERIFIED_REFERENCE_FIXUP_TABLES.has(refTable) &&
                        !TABLES_WITH_CUSTOM_REFERENCE_LOADER.has(table)
                    ) {
                        const strategy = plugins.getCoalesceStrategy(refTable)
                        const isDefaultView = refTable === VIEW_TABLE && refValue === DEFAULT_VIEW
                        // Only a lone coalesce key can be expressed as the field's value.
                        const [coalesceKey] = Array.isArray(strategy) && strategy.length === 1 ? strategy : []
                        if (coalesceKey) {
                            properties[k] = isGUID(refValue)
                                ? refValue
                                : await factory.createReference({
                                      source: value,
                                      table: refTable,
                                      keys: { [coalesceKey]: isDefaultView ? 'NULL' : refValue },
                                      ...(isDefaultView ? { guid: refValue } : {}),
                                  })
                            continue
                        }
                    }

                    properties[k] = value
                }

                const value = await factory.createRecord({
                    source: callExpression,
                    table,
                    explicitId: record.get('$id'),
                    properties,
                })
                value.setTelemetryMeta({ table })
                return { success: true, value }
            },
        },
    ],
    files: [
        {
            matcher: /\.xml$/,
            async toRecord(file, { parser, logger }) {
                try {
                    const records = await parser.parsePayload(file)
                    const recordMap = new Map<string, Record>()
                    for (const record of records) {
                        const key = `${record.getTable()}::${record.getId().getValue()}`
                        const existing = recordMap.get(key)

                        const merged = existing
                            ? existing.merge(record.properties()) // merge properties only to retain the action
                            : record

                        recordMap.set(key, merged)
                    }

                    const mergedRecords = Array.from(recordMap.values())
                    const [mergedFirst, ...mergedRest] = mergedRecords
                    if (!mergedFirst) {
                        return { success: false }
                    }
                    return { success: true, value: mergedFirst.with(...mergedRest) }
                } catch (e) {
                    logger.debug(e)
                    return { success: false }
                }
            },
        },
    ],
})

